Fix this zipper so it stops at the shorter input instead of adding undefined values.

```ts
function zip<A, B>(left: A[], right: B[]): Array<[A, B]> {
  return left.map((value, index) => [value, right[index]]);
}
```

reference_patch:
@@ -1,3 +1,4 @@
 function zip<A, B>(left: A[], right: B[]): Array<[A, B]> {
-  return left.map((value, index) => [value, right[index]]);
+  const length = Math.min(left.length, right.length);
+  return left.slice(0, length).map((value, index) => [value, right[index]]);
 }

