Fix this interleave helper so remaining values from the longer input are appended.

```rust
fn interleave(left: &[i32], right: &[i32]) -> Vec<i32> {
    left.iter().zip(right).flat_map(|(&a, &b)| [a, b]).collect()
}
```

reference_patch:
@@ -1,3 +1,11 @@
 fn interleave(left: &[i32], right: &[i32]) -> Vec<i32> {
-    left.iter().zip(right).flat_map(|(&a, &b)| [a, b]).collect()
+    let mut result = Vec::with_capacity(left.len() + right.len());
+    let common = left.len().min(right.len());
+    for index in 0..common {
+        result.push(left[index]);
+        result.push(right[index]);
+    }
+    result.extend_from_slice(&left[common..]);
+    result.extend_from_slice(&right[common..]);
+    result
 }

